typedef unsigned int u_int;

class nglVector
{
public:
    float x, y, z, w;
    float &operator[](int i) { return ((float *)this)[i]; }
    nglVector &operator=(const nglVector &v) { x=v.x; y=v.y; z=v.z; w=v.w; return *this; }
};

class nglMatrix
{
public:
    nglVector v[4];
};

class nglTexture;
extern void nglGetMatrix(nglMatrix &Dest, u_int ID);
extern void nglApplyMatrix(nglVector &dst, const nglMatrix m, const nglVector v);
extern int nglGetScreenWidth();
extern int nglGetScreenHeight();

inline int nglGetScreenXOffsetTV() { return 0; }
inline int nglGetScreenYOffsetTV() { return 0; }

template <class T> void unadjustCoords(T &x, T &y)
{
    x = (T) ((x-nglGetScreenXOffsetTV())*640.f/nglGetScreenWidth());
    y = (T) ((y-nglGetScreenYOffsetTV())*480.f/nglGetScreenHeight());
}

class IGOWidget
{
protected:
    bool display;
public:
    virtual ~IGOWidget();
    virtual void SetDisplay(const bool d = true);
    virtual void Update(const float dt);
    virtual void Draw(void);
    virtual bool GetDisplay(void) const;
};

class IconChallenge
{
public:
    class Task
    {
    public:
        enum TYPE { TYPE_AIR_FLIP, TYPE_AIR_GRAB, TYPE_AIR_SPIN, TYPE_AIR_POINTS_1000,
            TYPE_AIR_POINTS_2000, TYPE_AIR_POINTS_5000, TYPE_AIR_SPECIAL, TYPE_FACE_SPIN,
            TYPE_TUBE_TIME_10, TYPE_TUBE_TIME_15, TYPE_TUBE_TIME_30, TYPE_TUBE_TRICK,
            TYPE_NUM, TYPE_NONE };
        bool IsCompleted(void) const;
        TYPE GetType(void) const;
        nglVector GetPosition(void) const;
    };
    class Sequence
    {
    public:
        int GetNumTasks(void) const;
        const Task *GetTask(const int i) const;
    };
    const Sequence *GetCurrentSequence(void) const;
};

class IconRadarWidget : public IGOWidget
{
    struct OnscreenIcon { nglVector screenPos; nglTexture *texture; };
    void *ellipsePQ;
    IconChallenge *challenge;
    int numIconTextures;
    nglTexture **iconTextures;
    int numOnscreenIcons;
    OnscreenIcon *onscreenIcons;
public:
    void Update(const float dt);
};

void IconRadarWidget::Update(const float dt)
{
    const IconChallenge::Sequence * currSequence;
    nglMatrix mat;
    nglVector dest;
    int i;

    IGOWidget::Update(dt);

    nglGetMatrix(mat, 2);
    numOnscreenIcons = 0;
    if (challenge && challenge->GetCurrentSequence())
    {
        currSequence = challenge->GetCurrentSequence();
        for (i = 0; i < currSequence->GetNumTasks(); i++)
        {
            if (!currSequence->GetTask(i)->IsCompleted())
            {
                onscreenIcons[numOnscreenIcons].texture = iconTextures[currSequence->GetTask(i)->GetType()];
                onscreenIcons[numOnscreenIcons].screenPos[0] = currSequence->GetTask(i)->GetPosition().x;
                onscreenIcons[numOnscreenIcons].screenPos[1] = currSequence->GetTask(i)->GetPosition().y;
                onscreenIcons[numOnscreenIcons].screenPos[2] = currSequence->GetTask(i)->GetPosition().z;
                onscreenIcons[numOnscreenIcons].screenPos[3] = 1;
                nglApplyMatrix(dest, mat, onscreenIcons[numOnscreenIcons].screenPos);
                onscreenIcons[numOnscreenIcons].screenPos = dest;
                unadjustCoords(onscreenIcons[numOnscreenIcons].screenPos[0], onscreenIcons[numOnscreenIcons].screenPos[1]);
                numOnscreenIcons++;
            }
        }
    }
}
